// ======================================================================
// Policy struct
// ======================================================================

pub struct StaticRecordBytesPolicy {
    /// W3C SCXML 5.2: the `last` datamodel variable, published (`sce:direction="out"`).
    last: StaticRecordBytesFramedRecord,
    /// W3C SCXML 5.2: the `spare` datamodel variable, published (`sce:direction="out"`).
    spare: Vec<u8>,
    /// W3C SCXML 5.2: the `frames` datamodel variable, published (`sce:direction="out"`).
    frames: Vec<StaticRecordBytesFramedRecord>,
    /// W3C SCXML 5.2: the `size` datamodel variable, published (`sce:direction="out"`).
    size: u32,
    /// W3C SCXML 5.2: the `matches` datamodel variable, published (`sce:direction="out"`).
    matches: u32,
    /// W3C SCXML 5.2: the `misses` datamodel variable, published (`sce:direction="out"`).
    misses: u32,
    /// W3C SCXML 5.2: the `leads` datamodel variable, published (`sce:direction="out"`).
    leads: u32,
    /// W3C SCXML 5.2: the `errors` datamodel variable, published (`sce:direction="out"`).
    errors: u32,
    // W3C SCXML 5.10: the session's id (script engine, invoke tracking, the
    // saved state), bound when the machine is built and never empty
    // (docs/adr/0045): drawn, given by the host, or given by the parent.
    pub session_id: Option<String>,
    // W3C SCXML 6.4: Parent engine external queue for #_parent send routing
    // Always generated under std — any SM can be invoked as a child. Under
    // `--no-std` (SCE Protocol-Synthesis RFC §synth-5-J-2) the SCXML `<invoke>` element
    // is codegen-rejected, so no parent_external_queue handle is ever
    // wired in, and the Arc<Mutex<...>> (alloc-coupled) is omitted.
    pub parent_external_queue: Option<std::sync::Arc<std::sync::Mutex<Vec<(String, String)>>>>,
    // W3C SCXML 6.4.1: This child's invoke ID (for _event.invokeid in parent).
    // SCE Protocol-Synthesis RFC §synth-5-J-2: gated to !no_std — `<invoke>` is codegen-rejected
    // under no_std, so a machine is never instantiated as a child and this
    // identity is dead. Mirrors the `parent_external_queue` / `invoke` module gate.
    pub invoke_id: String,
    // W3C SCXML 6.5: Child session ID for finalize origin matching.
    pub child_session_id: String,
}

impl StaticRecordBytesPolicy {
    fn build(session_id: String) -> Self {
        let last: StaticRecordBytesFramedRecord = StaticRecordBytesFramedRecord {
            sensor: 1,
            frame: b"ab".to_vec(),
        };
        let spare: Vec<u8> = b"hello".to_vec();
        let frames: Vec<StaticRecordBytesFramedRecord> = Vec::new();
        let size: u32 = 0;
        let matches: u32 = 0;
        let misses: u32 = 0;
        let leads: u32 = 0;
        let errors: u32 = 0;
        Self {
            last,
            spare,
            frames,
            size,
            matches,
            misses,
            leads,
            errors,
            session_id: Some(session_id),
            parent_external_queue: None,
            invoke_id: String::new(),
            child_session_id: String::new(),
        }
    }

    /// Build the machine under a session id drawn from the operating system's
    /// randomness, a UUID version 4 (docs/adr/0045).
    ///
    /// Absent on a target with no source of randomness the runtime reads
    /// (`wasm32-unknown-unknown`): a host there gives the id, through
    /// [`new_with_session_id`](Self::new_with_session_id).
    #[cfg(not(any(target_os = "none", all(target_arch = "wasm32", target_os = "unknown"))))]
    pub fn new() -> Self {
        Self::build(::sce_rust_runtime::helpers::session_id::drawn())
    }

    /// Build the machine under the session id its host gives: the host's own
    /// name for the machine, say, or a fixed id a test holds a saved text to
    /// (docs/adr/0045, "Questions the owner answered" 2). `_sessionid` is bound
    /// here and kept until the session ends; a restore binds the saved id in
    /// its place, since the session carries on.
    ///
    /// With [`new_with_checked_session_id`](Self::new_with_checked_session_id),
    /// the way this machine is built on `wasm32-unknown-unknown`, which has no
    /// source of randomness the runtime reads.
    ///
    /// # Errors
    ///
    /// An id that is not an XML Nmtoken (the empty text, a space, a `#`) is
    /// refused with the reason, and no machine is built.
    pub fn new_with_session_id(
        session_id: &str,
    ) -> Result<Self, ::sce_rust_runtime::helpers::session_id::SessionIdRefusal> {
        Ok(Self::build(::sce_rust_runtime::helpers::session_id::given(
            session_id,
        )?))
    }

    /// [`new_with_session_id`](Self::new_with_session_id) under an id already
    /// proven to be an XML Nmtoken (docs/adr/0073), so nothing is refused. With
    /// the id written as `sce_rust_runtime::session_id!("...")`, a bad one is a
    /// compile error and the program carries no run-time check of it.
    pub fn new_with_checked_session_id(
        session_id: ::sce_rust_runtime::helpers::session_id::SessionId,
    ) -> Self {
        Self::build(session_id.as_str().to_string())
    }

    /// The policy of a child its parent invokes, under the id the tree gives it,
    /// `<parent>.<invokeid>` (docs/adr/0045): formed by the parent from its own
    /// id and the invoke id, both held to the rule already, so it is not
    /// judged again.
    pub(crate) fn for_child(session_id: String) -> Self {
        Self::build(session_id)
    }

    /// §scxml-6.4.1: give this machine the values `params` carries, in place of
    /// the ones its `<data>` gave. Called before it initializes.
    pub fn accept_params(&mut self, params: StaticRecordBytesInvokeParams) {
        if let Some(value) = params.size {
            self.size = value;
        }
        if let Some(value) = params.matches {
            self.matches = value;
        }
        if let Some(value) = params.misses {
            self.misses = value;
        }
        if let Some(value) = params.leads {
            self.leads = value;
        }
        if let Some(value) = params.errors {
            self.errors = value;
        }
    }

    /// W3C SCXML 5.2: what the published `last` datamodel variable
    /// holds now. Only the machine writes it.
    pub fn last(&self) -> &StaticRecordBytesFramedRecord {
        &self.last
    }

    /// W3C SCXML 5.2: what the published `spare` datamodel variable
    /// holds now. Only the machine writes it.
    pub fn spare(&self) -> &[u8] {
        &self.spare
    }

    /// W3C SCXML 5.2: what the published `frames` datamodel variable
    /// holds now. Only the machine writes it.
    pub fn frames(&self) -> &[StaticRecordBytesFramedRecord] {
        &self.frames
    }

    /// W3C SCXML 5.2: what the published `size` datamodel variable
    /// holds now. Only the machine writes it.
    pub fn size(&self) -> u32 {
        self.size
    }

    /// W3C SCXML 5.2: what the published `matches` datamodel variable
    /// holds now. Only the machine writes it.
    pub fn matches(&self) -> u32 {
        self.matches
    }

    /// W3C SCXML 5.2: what the published `misses` datamodel variable
    /// holds now. Only the machine writes it.
    pub fn misses(&self) -> u32 {
        self.misses
    }

    /// W3C SCXML 5.2: what the published `leads` datamodel variable
    /// holds now. Only the machine writes it.
    pub fn leads(&self) -> u32 {
        self.leads
    }

    /// W3C SCXML 5.2: what the published `errors` datamodel variable
    /// holds now. Only the machine writes it.
    pub fn errors(&self) -> u32 {
        self.errors
    }
}

// docs/adr/0045: a machine built with no arguments draws its session id, so it
// has a default only where `new` can draw one.
#[cfg(not(any(target_os = "none", all(target_arch = "wasm32", target_os = "unknown"))))]
impl Default for StaticRecordBytesPolicy {
    fn default() -> Self {
        Self::new()
    }
}

